class Solution:
    def sortArray(self, nums: List[int]) -> List[int]:
        def mergeSortedArrays(left: list[int], m: int, right: list[int], n: int):
            ans = [0] * (m + n)
            i, j = 0, 0
            curr = 0
            while i < m and j < n:
                if left[i] < right[j]:
                    ans[curr] = left[i]
                    i += 1
                else:
                    ans[curr] = right[j]
                    j += 1
                curr += 1

            while i < m:
                ans[curr] = left[i]
                i += 1
                curr += 1

            while j < n:
                ans[curr] = right[j]
                j += 1
                curr += 1
            return ans

        def mergeSort(nums: list[int], n: int):
            if n == 1:
                return nums

            mid = n // 2
            left = mergeSort(nums[0:mid], mid)
            right = mergeSort(nums[mid:n], n - mid)

            return mergeSortedArrays(left, mid, right, n - mid)

        return mergeSort(nums, len(nums))
